namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Instructor { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }

    public string FullCode => $"{DepartmentCode} {CourseNumber}";
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "101", Title = "Introduction to Programming", Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", Instructor = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "TTh 10:30–11:45 AM", Instructor = "Dr. James Martinez", InstructorBio = "Dr. Martinez specializes in algorithm optimization and has contributed to several open-source projects. He received his Ph.D. from Stanford University.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "310", Title = "Database Systems", Description = "Design and implementation of database systems. Covers relational model, SQL, normalization, transaction management, and NoSQL databases.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", Instructor = "Dr. Lisa Park", InstructorBio = "Dr. Park worked at Oracle for a decade before joining academia. Her research focuses on distributed database systems and query optimization." },
            new() { Id = 4, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "450", Title = "Machine Learning", Description = "Introduction to machine learning algorithms including supervised learning, unsupervised learning, and neural networks. Includes hands-on projects with real datasets.", Credits = 4, Schedule = "TTh 2:00–3:15 PM", Instructor = "Dr. Alex Kumar", InstructorBio = "Dr. Kumar leads the university's AI research lab and has published over 50 papers on deep learning and computer vision." },
            new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", Instructor = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor is an award-winning educator who has taught calculus for over 20 years. He is known for making abstract concepts accessible to all students.", IsFeatured = true },
            new() { Id = 6, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "210", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors with applications.", Credits = 3, Schedule = "TTh 9:00–10:15 AM", Instructor = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez's research in applied mathematics bridges pure theory and computational methods. She received the Distinguished Teaching Award in 2023." },
            new() { Id = 7, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", Instructor = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor is an award-winning educator who has taught calculus for over 20 years. He is known for making abstract concepts accessible to all students." },
            new() { Id = 8, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions demonstrating physical principles.", Credits = 4, Schedule = "MWF 10:00–10:50 AM, Lab: F 2:00–4:00 PM", Instructor = "Dr. David Wilson", InstructorBio = "Dr. Wilson is an experimental physicist whose research on quantum materials has been featured in Nature and Science.", IsFeatured = true },
            new() { Id = 9, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Continuation of General Physics I with laboratory.", Credits = 4, Schedule = "MWF 10:00–10:50 AM, Lab: W 2:00–4:00 PM", Instructor = "Dr. Emily Zhang", InstructorBio = "Dr. Zhang researches quantum optics and photonic devices. She joined the department after a postdoc at CERN." },
            new() { Id = 10, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "101", Title = "Freshman Composition", Description = "Develops critical reading, writing, and thinking skills. Students write multiple essays in various rhetorical modes.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", Instructor = "Prof. Katherine Brooks", InstructorBio = "Prof. Brooks is a published author and writing coach. She has helped thousands of students develop their writing voice over her 18-year career." },
            new() { Id = 11, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "240", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Examines major works in their historical and cultural contexts.", Credits = 3, Schedule = "TTh 1:00–2:15 PM", Instructor = "Dr. Michael Foster", InstructorBio = "Dr. Foster specializes in 20th-century American fiction and has authored two books on the Harlem Renaissance.", IsFeatured = true },
            new() { Id = 12, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "101", Title = "World History I", Description = "Survey of world civilizations from ancient times to 1500 CE. Explores political, social, and cultural developments across regions.", Credits = 3, Schedule = "TTh 11:00 AM–12:15 PM", Instructor = "Dr. Angela Rivera", InstructorBio = "Dr. Rivera is an archaeologist and historian whose fieldwork in Mesoamerica has uncovered new insights into pre-Columbian societies." },
            new() { Id = 13, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "250", Title = "Modern European History", Description = "Europe from the Enlightenment to the present day. Topics include revolution, industrialization, world wars, and European integration.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", Instructor = "Dr. Thomas Wright", InstructorBio = "Dr. Wright is a specialist in Cold War history and has served as a consultant for several documentary films." }
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.FullCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return request.CourseId > 0
            && !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId);
    }
}

